def process_refund(args, session):
    if not session.get("verified_customer_id"):
        return {"error": "Cannot process refund — customer identity "
                         "not verified. Call get_customer first."}
    return do_refund(args["customer_id"], args["amount"])

# PostToolUse: normalise heterogeneous tool output
def post_tool_use(tool_name, result):
    result["date"] = to_iso8601(result.get("date"))
    result["status"] = STATUS_MAP.get(result.get("status"), result.get("status"))
    return result

# Pre-execution interception: enforce policy before the tool runs
def pre_tool_use(tool_name, args, session):
    if tool_name == "process_refund" and args["amount"] > 500:
        return Block("Refund > $500 requires human approval")
    if tool_name == "transfer_funds" and not session.get("aml_passed"):
        return Block("AML check required before transfer")
    return Allow()
